INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle Arbeitszeitmodelle gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel wählbar"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Arbeitszeitmodellen?', 3, '[{"text": "Flexibilität erhöhen", "correct": true, "because": "Anpassung an Bedürfnisse"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Produktivität erzwingen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitszeitmodelle gibt es?', 5, '[{"text": "Gleitzeit", "correct": true, "because": "Flexible Arbeitszeiten"}, {"text": "Schichtarbeit", "correct": true, "because": "Rund-um-die-Uhr"}, {"text": "Urlaubszeit", "correct": false, "because": "Kein Arbeitsmodell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gleitzeit erlaubt flexible Arbeitszeiten. b) Schichtarbeit ist immer unflexibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schichtarbeit kann flexibel sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Arbeitszeitmodells?', 4, '[{"text": "Mitarbeiterbedürfnisse", "correct": false, "because": "Entscheidend für Akzeptanz"}, {"text": "Arbeitsanforderungen", "correct": false, "because": "Bestimmt Modell"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Teilzeit ein Arbeitszeitmodell ist?', 2, '[{"text": "Ja", "correct": true, "because": "Reduzierte Stunden"}, {"text": "Nein", "correct": false, "because": "Teil der Modelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Arbeitszeitmodell passt für flexible Arbeitszeiten?', 3, '[{"text": "Gleitzeit", "correct": true, "because": "Eigene Zeitwahl"}, {"text": "Schichtarbeit", "correct": false, "because": "Feste Zeiten"}, {"text": "Vollzeit", "correct": false, "because": "Standardmodell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Schichtarbeit?', 5, '[{"text": "Feste Schichtzeiten", "correct": true, "because": "Geplante Abläufe"}, {"text": "Wechselnde Teams", "correct": true, "because": "Rund-um-die-Uhr"}, {"text": "Flexible Pausen", "correct": false, "because": "Streng geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitszeitmodelle verbessern die Work-Life-Balance. b) Sie sind immer starr. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitszeitmodellen unwichtig?', 4, '[{"text": "Arbeitszeitregelung", "correct": false, "because": "Kernaspekt"}, {"text": "Mitarbeiterwünsche", "correct": false, "because": "Fördert Zufriedenheit"}, {"text": "Firmenfarben", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Gleitzeit immer ohne Kernzeit?', 2, '[{"text": "Nein", "correct": true, "because": "Oft mit Kernzeit"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Teilzeit als Arbeitszeitmodell?', 4, '[{"text": "Work-Life-Balance", "correct": true, "because": "Mehr Freizeit"}, {"text": "Flexibilität", "correct": true, "because": "Weniger Stunden"}, {"text": "Höhere Produktivität", "correct": false, "because": "Abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schichtarbeit immer ungesund ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mit Pausen gesund"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Arbeitszeitmodellen?', 3, '[{"text": "Mitarbeiterzufriedenheit", "correct": true, "because": "Fördert Motivation"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Technologie", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gleitzeit erlaubt eigene Zeitwahl. b) Teilzeit bedeutet immer 40 Stunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teilzeit weniger Stunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Schichtarbeit?', 5, '[{"text": "Ungesunde Schlafzeiten", "correct": true, "because": "Nachtschichten"}, {"text": "Weniger Flexibilität", "correct": true, "because": "Feste Pläne"}, {"text": "Höhere Produktivität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitszeitmodellen unwichtig?', 3, '[{"text": "Arbeitszeitregelung", "correct": false, "because": "Kernaspekt"}, {"text": "Mitarbeiterbedarf", "correct": false, "because": "Entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Gleitzeit Überstunden erlauben?', 3, '[{"text": "Ja", "correct": true, "because": "Innerhalb Grenzen"}, {"text": "Nein", "correct": false, "because": "Flexibel geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Teilzeit gesetzlich geregelt ist?', 2, '[{"text": "Ja", "correct": true, "because": "Teilzeit- und Befristungsgesetz"}, {"text": "Nein", "correct": false, "because": "Gesetzlich abgedeckt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Modell wähle ich für 24/7-Betrieb?', 4, '[{"text": "Schichtarbeit", "correct": true, "because": "Rund-um-die-Uhr"}, {"text": "Gleitzeit", "correct": false, "because": "Individuelle Flexibilität"}, {"text": "Teilzeit", "correct": false, "because": "Reduzierte Stunden"}]');
